int card_toshiro_umezawa(int player, int card, event_t event){
/*
Toshiro Umezawa |1|B|B
Legendary Creature â Human Samurai 2/2
Bushido 1 (Whenever this creature blocks or becomes blocked, it gets +1/+1 until end of turn.)
Whenever a creature an opponent controls dies, you may cast target instant card from your graveyard.
	If that card would be put into a graveyard this turn, exile it instead.
*/
	check_legend_rule(player, card, event);

	if( event == EVENT_GRAVEYARD_FROM_PLAY ){
		count_for_gfp_ability(player, card, event, 1-player, TYPE_CREATURE, NULL);
	}

	int amount = resolve_gfp_ability(player, card, event, RESOLVE_TRIGGER_AI(player));
	if( amount && ! graveyard_has_shroud(player) ){
		int cont = 1;
		while( cont ){
				int playable[2][amount];
				int pc = 0;
				const int *grave = get_grave(player);
				int i = 0;
				while( grave[i] != -1 ){
						if( is_what(-1, grave[i], TYPE_INSTANT | TYPE_INTERRUPT) && can_play_iid(player, event, grave[i]) ){
							playable[0][pc] = grave[i];
							playable[1][pc] = i;
							pc++;
							if( pc == amount ){
								break;
							}
						}
						i++;
				}

				if( pc ){
					test_definition_t this_test;
					new_default_test_definition(&this_test, TYPE_ANY, "Select an Instant to play");

					int selected = select_card_from_zone(player, player, playable[0], pc, 0, AI_MAX_VALUE, -1, &this_test);
					if( selected != -1 ){
						if( charge_mana_from_id(player, card, event, cards_data[playable[0][selected]].id) ){
							play_card_in_grave_for_free_and_exile_it(player, player, playable[1][selected]);
							pc--;
							cont = pc > 0 ? 1 : 0;
						}
					}
					else{
						cont = 0;
					}
				}
		}
	}

	return bushido(player, card, event, 1);
}

int card_havengul_lich(int player, int card, event_t event){
/* CARD_ID_HAVENGUL_LICH	12200
Havengul Lich	|3|U|B
Creature - Zombie Wizard 4/4
|1: You may cast target creature card in a graveyard this turn.
When you cast that card this turn, ~ gains all activated abilities of that card until end of turn. */

	target_definition_t td;
	default_target_definition(player, card, &td, TYPE_CREATURE);
	td.zone = TARGET_ZONE_PLAYERS;
	td.illegal_abilities = 0;

	card_instance_t *instance = get_card_instance(player, card);

	if( event == EVENT_CAN_ACTIVATE && can_use_activated_abilities(player, card) ){
		int result = 0;
		if( has_mana_for_activated_ability(player, card, MANACOST_X(1)) && ! graveyard_has_shroud(2) ){
			result |= can_cast_creature_in_grave_with_havengul_lich(player, card);
		}
		result |= (player == AI ? 0 : can_use_stolen_ability_with_havengul_lich(player, card));
		return result;
	}

	if(event == EVENT_ACTIVATE ){
		int choice = 0;
		if( can_cast_creature_in_grave_with_havengul_lich(player, card) ){
			if( can_use_stolen_ability_with_havengul_lich(player, card) ){
				choice = do_dialog(player, player, card, -1, -1, " Cast a creature from grave\n Use a stolen ability\n Cancel", 0);
			}
		}
		else{
			choice = 1;
		}
		if( choice == 0 ){
			if( charge_mana_for_activated_ability(player, card, 1, 0, 0, 0, 0, 0) ){
				instance->targets[0].player = 1-player;
				if( can_cast_creature_in_grave(player, card, 1-player) ){
					if( player != AI && can_cast_creature_in_grave(player, card, player) ){
						if( pick_target(&td, "TARGET_PLAYER") ){
							instance->number_of_targets = 1;
						}
						else{
							spell_fizzled = 1;
							return 0;
						}
					}
				}
				else{
					instance->targets[0].player = player;
				}

				test_definition_t this_test;
				new_default_test_definition(&this_test, TYPE_CREATURE, "Select a creature card");
				this_test.special_selection_function = &can_cast_this;
				int selected = select_target_from_grave_source(player, card, instance->targets[0].player, 0, AI_MAX_CMC, &this_test, 1);
				if( selected != -1 ){
					instance->info_slot = 66;
				}
				if( selected == -1 ){
					spell_fizzled = 1;
					return 0;
				}
			}
		}
		else if( choice == 1 ){
				int act_array[8];
				int aa_count = 0;
				int i=2;
				while( i<10 ){
						if( instance->targets[i].card != -1 ){
							card_data_t card_d = cards_data[ instance->targets[i].card ];
							CardFunction ptFunction = card_d.code_pointer;
							if( ptFunction(player, card, EVENT_CAN_ACTIVATE ) ){
								act_array[aa_count] = instance->targets[i].card;
								aa_count++;
							}
						}
						i++;
				}
				test_definition_t this_test;
				new_default_test_definition(&this_test, TYPE_CREATURE, "Select an ability to activate.");
				int selected = select_card_from_zone(player, player, act_array, aa_count, 0, AI_MAX_VALUE, -1, &this_test);
				if( selected != -1 ){
					card_data_t* card_d = &cards_data[ act_array[selected] ];
					CardFunction ptFunction = card_d->code_pointer;
					ptFunction(player, card, EVENT_ACTIVATE);
					if( spell_fizzled != 1 ){
						instance->targets[1].card = act_array[selected];
						instance->info_slot = 67;
					}
					else{
						return 0;
					}
				}
				else{
					spell_fizzled = 1;
					return 0;
				}
		}
		else{
			spell_fizzled = 1;
			return 0;
		}
	}

	else if( event == EVENT_RESOLVE_ACTIVATION ){
			card_instance_t *parent = get_card_instance(instance->parent_controller, instance->parent_card);
			if( instance->info_slot == 66 ){
				int selected = validate_target_from_grave_source(player, card, instance->targets[0].player, 1);
				if( selected != -1 ){
					const int *grave = get_grave(instance->targets[0].player);
					int id = cards_data[grave[selected]].id;
					if( charge_mana_from_id(player, -1, event, id) ){
						if( (cards_data[grave[selected]].extra_ability & EA_ACT_ABILITY) ||
							(cards_data[grave[selected]].extra_ability & EA_MANA_SOURCE)
						  ){
							int i = 2;
							while(i<10 ){
								if( parent->targets[i].player == -1 ){
									parent->targets[i].card = grave[selected];
									break;
								}
								i++;
							}
						}
						int dead = play_card_in_grave_for_free(player, instance->targets[0].player, selected);
						if( instance->targets[0].player != player ){
							card_instance_t *this = get_card_instance(player, dead);
							this->state |= STATE_OWNED_BY_OPPONENT;
						}
					}
				}
			}
			if( instance->info_slot == 67 ){
				card_data_t* card_d = &cards_data[ instance->targets[1].card ];
				CardFunction ptFunction = card_d->code_pointer;
				ptFunction(instance->parent_controller, instance->parent_card, EVENT_RESOLVE_ACTIVATION);
			}
	}

	if( event == EVENT_CLEANUP ){
		int i;
		for(i=2; i<10; i++){
			instance->targets[i].player = -1;
			instance->targets[i].card = -1;
		}
	}

	return 0;
}

int card_sehts_tiger(int player, int card, event_t event){
/*
Seht's Tiger |2|W|W
Creature â Cat 3/3
Flash (You may cast this spell any time you could cast an instant.)
When Seht's Tiger enters the battlefield, you gain protection from the color of your choice until end of turn.
(You can't be targeted, dealt damage, or enchanted by anything of the chosen color.)
*/
	etb_ability(player, card, event, RESOLVE_TRIGGER_MANDATORY);

	if( event == EVENT_ETB_ABILITY ){
		get_card_instance(player, card)->info_slot = 1<<choose_a_color(player, get_deck_color(player, 1-player));
	}

	if( event == EVENT_CLEANUP ){
		get_card_instance(player, card)->info_slot = 0;
	}

	return flash(player, card, event);
}

int card_personal_incarnation(int player, int card, event_t event){
/* CARD_ID_PERSONAL_INCARNATION	181
Personal Incarnation	|3|W|W|W
Creature - Avatar Incarnation 6/6
|0: The next 1 damage that would be dealt to ~ this turn is dealt to its owner instead. Only ~'s owner may activate this ability.
When ~ dies, its owner loses half his or her life, rounded up. */

	if( this_dies_trigger(player, card, event, RESOLVE_TRIGGER_MANDATORY) ){
		int amount = round_up_value(life[get_owner(player, card)]);
		lose_life(get_owner(player, card), amount);
	}

	if( ! IS_GAA_EVENT(event) || get_owner(player, card) != player ){
		return 0;
	}

	target_definition_t td;
	default_target_definition(player, card, &td, TYPE_EFFECT);
	td.special = TARGET_SPECIAL_EXTRA_FUNCTION;
	td.extra = (int)is_damaging_attached_creature;
	td.illegal_abilities = 0;

	card_instance_t *instance = get_card_instance(player, card);

	if( event == EVENT_RESOLVE_ACTIVATION ){
		if( valid_target(&td) ){
			card_instance_t *dmg = get_card_instance(instance->targets[0].player, instance->targets[0].card);
			dmg->damage_target_player = instance->parent_controller;
			dmg->damage_target_card = -1;
		}
	}

	return generic_activated_ability(player, card, event, GAA_DAMAGE_PREVENTION | GAA_CAN_TARGET, MANACOST0, 0, &td, "TARGET_DAMAGE");
}

