	}

	if( ! IS_AURA_EVENT(player, card, event) ){
		return 0;
	}

	target_definition_t td;
	default_target_definition(player, card, &td, TYPE_LAND);
	td.preferred_controller = 1-player;
	return targeted_aura(player, card, event, &td, "TARGET_LAND");
}

