							default_test_definition(&this_test, TYPE_CREATURE);
							this_test.type_flag = F1_IS_TOKEN;
							this_test.id = id;
							APNAP(p, {new_manipulate_all(player, card, p, &this_test, KILL_EXILE);};);
					}
				}
			}
		}

		if( leaves_play(player, card, event) ){
			int i;
			for(i=0; i<2; i++){
