	if( p > -1 && c > -1 ){
		if( ! is_humiliated(p, c) ){
			upkeep_trigger_ability_mode(player, card, event, player, RESOLVE_TRIGGER_AI(player));

			if (event == EVENT_UPKEEP_TRIGGER_ABILITY){

