		if( type == TYPE_CREATURE ){
			pos+=scnprintf(buffer+pos, 100-pos, " creature");
		}
		if( type == TYPE_ARTIFACT ){
			pos+=scnprintf(buffer+pos, 100-pos, "n artifact");
		}
