							  "Discard", 1, 1);
		  if (choice == 1)
			lose_life(trigger_cause_controller, 3);
		  else
			new_discard_card(trigger_cause_controller, trigger_cause, player, 0);
		}
	}

  return global_enchantment(player, card, event);
}

