}

static int put_commander_from_command_zone_to(int player, int where){
	enum{
			COMM_IN_COMMAND_ZONE 	= 0,
			COMM_IN_PLAY 			= 1,
			COMM_MISSING_IN_ACTION 	= 2
	};

	int edh_card = locate_edh_card(player);
	int commander_card = -1;
	if( edh_card != -1 ){
		card_instance_t *instance = get_card_instance(player, edh_card);
		if( instance->targets[3].player > -1 ){
			if( instance->targets[3].player & COMM_IN_COMMAND_ZONE ){
				remove_card_from_rfg(player, cards_data[instance->info_slot].id);
				instance->targets[3].player = COMM_MISSING_IN_ACTION; //So the "commander legacy" will be attached
				commander_card = add_card_to_hand(player, instance->info_slot);
				if( where == TUTOR_PLAY_TAPPED ){
					add_state(player, commander_card, STATE_TAPPED);
				}
				if( where == TUTOR_PLAY_TAPPED || where == TUTOR_PLAY){
					set_special_flags2(player, commander_card, SF2_COMMANDER);
					put_into_play(player, commander_card);
				}
			}
		}
	}

	return commander_card;
}

static int is_commander_in_command_zone(int player){
	enum{
			COMM_IN_COMMAND_ZONE 	= 0,
			COMM_IN_PLAY 			= 1,
			COMM_MISSING_IN_ACTION 	= 2
	};

	int edh_card = locate_edh_card(player);
	if( edh_card != -1 ){
		card_instance_t *instance = get_card_instance(player, edh_card);
		if( instance->targets[3].player > -1 ){
			return (instance->targets[3].player & COMM_IN_COMMAND_ZONE) ? 1 : 0;
		}
	}

	return 0;
}

void ai_assign_blockers(int player)
{
  // 0x4b18e0

  EXE_FN(void, 0x4AF6F0, int)(player);	//TENTATIVE_ai_speculate_on_combat(player);

  EXE_DWORD(0x60827C) = -9999;

  int i;
  for (i = 0; i < 16; ++i)
	EXE_DWORD_PTR(0x6076D8)[i] = 0;

  EXE_FN(int, 0x4B1A50, int, int)(player, 0);

  if (!(ai_is_speculating == 1 || current_turn == HUMAN))
	return;

  // Begin additions
  if (event_flags & EF_ATTACKER_CHOOSES_BLOCKERS)
	{
	  if (!(ai_is_speculating == 1 || current_turn == AI))	// if speculating or AI is attacking, nothing blocks
		human_assign_blockers(player);
	  return;
	}
  // End additions

  for (i = 0; i < EXE_DWORD(0x607D54); ++i)
	{
      forbid_attack = 0;
	  if (event_flags & EA_PAID_BLOCK)
		{
		  EXE_FN(void, 0x435C80, void)();	//push_affected_card_stack()
		  trigger_cause_controller = EXE_DWORD(0x607C2C);	//TENTATIVE_ai_speculation_opponent
		  trigger_cause = EXE_DWORD_PTR(0x608304)[i];		//WILDGUESS_ai_combat_block_card[i]
		  dispatch_trigger(1 - current_turn, TRIGGER_PAY_TO_BLOCK, EXE_STR(0x790248)/*PROMPT_TURNSEQUENCE[0]*/, 1);
		  EXE_FN(void, 0x435CD0, void)();	//pop_affected_card_stack()
		  if (forbid_attack)
			{
			  forbid_attack = 0;
			  continue;
			}
		}

	  uint8_t blk = BYTE0(EXE_DWORD_PTR(0x60775C)[i]);

	  card_instance_t* instance = get_card_instance(EXE_DWORD(0x607C2C),	// TENTATIVE_ai_speculation_opponent
													EXE_DWORD_PTR(0x608304)[i]);	// WILDGUESS_ai_combat_block_card[i]
	  // Begin additions
	  if (instance->blocking != 255)	// Already during one of the two triggers dispatched from here
		continue;
	  // End additions
	  instance->blocking = blk;

	  if (blk != 255)	// Originally !(blk & 0x80) - this failed when blocking ids 128-149
		instance->state |= STATE_BLOCKING;

	  if (ai_is_speculating != 1)
		{
		  /* All this does is SendMessageA(hwnd_MainClass, 0x464u, 0xFFu, 0).  It's always called through a wrapper that checks ai_is_speculating != 1
		   * (except from C where it's already been checked).  wndproc_MainClass responds by calling TENTATIVE_redisplay_all(0, 0xff) at 0x437ec0. */
		  EXE_FN(void, 0x437E20, void)();

		  if (blk != 255)
			play_sound_effect(WAV_BLOCK2);
		}

	  /* This immediately followed the EA_PAID_BLOCK/TRIGGER_PAY_TO_BLOCK.  Putting it down here matches the order when a human blocks; in particular,
	   * instance->blocking is correct during TRIGGER_BLOCKER_CHOSEN, which is necessary for Tromokratis. */
	  if ((event_flags & EA_SELECT_BLOCK) && blk != 255)
		dispatch_trigger2(current_turn, TRIGGER_BLOCKER_CHOSEN, EXE_STR(0x790074), 0,//PROMPT_BLOCKERSELECTION[0]
						  EXE_DWORD(0x607C2C),	//TENTATIVE_ai_speculation_opponent
						  EXE_DWORD_PTR(0x608304)[i]);		//WILDGUESS_ai_combat_block_card[i]
	}
}

int enchant_player(int player, int card, event_t event, target_definition_t *td){

	card_instance_t *instance = get_card_instance(player, card);

	if( event == EVENT_SHOULD_AI_PLAY ){
		return should_ai_play(player, card);
	}

	if( event == EVENT_CAN_CAST ){
		return can_target(td);
	}

	if( event == EVENT_CAST_SPELL && affect_me(player, card) ){
		if( ! check_special_flags(player, card, SF_TARGETS_ALREADY_SET) ){
			load_text(0, "TARGET_PLAYER");
			int result = select_target(td->player, td->card, td, text_lines[0], NULL);
			if( ! result ){
				spell_fizzled = 1;
			}
		}
	}

	if( event == EVENT_RESOLVE_SPELL ){
		if( ! valid_target(td) ){
			kill_card(player, card, KILL_SACRIFICE);
		}
		else{
			instance->targets[4] = instance->targets[0];
		}
	}

	return 0;
}

void minimum_blockers(int player, int card, int event, int min){
	if( event == EVENT_DECLARE_BLOCKERS ){
		// If there are fewer than 3 creatures blocking me, then no one is
		// blocking me
		int block_count = 0;
		int count = 0;
		while(count < active_cards_count[1-player]){
			if(in_play(1-player, count) ){
				card_instance_t *instance = get_card_instance( 1-player, count);
				if( instance->blocking == card ){
					block_count++;
				}
			}
			count++;
		}

		if( block_count < min ){
			count = 0;
			while(count < active_cards_count[1-player]){
				if(in_play(1-player, count) ){
					card_instance_t *instance = get_card_instance( 1-player, count);
					if( instance->blocking == card ){
						instance->blocking = 255;
						instance->state &= ~(STATE_BLOCKED|STATE_BLOCKING);
					}
				}
				count++;
			}
		}
	}
}

int enchanted_land_has_T_add_n_mana_of_any_one_color(int player, int card, event_t event, int amt){

	if( in_play(player, card) && get_card_instance(player, card)->damage_target_player > -1 ){
		card_instance_t *instance = get_card_instance( player, card );
		int p = instance->damage_target_player;
		int c = instance->damage_target_card;

		if( event == EVENT_CAN_ACTIVATE ){
			return mana_producer(p, c, event);
		}

		if( event == EVENT_ACTIVATE ){
			produce_mana_tapped_all_one_color(p, c, COLOR_TEST_ANY_COLORED, amt);
			if (cancel != 1){
				// tap_card() would do this, but clear tapped_for_mana_color first.
				dispatch_event(p, c, EVENT_TAP_CARD);
			}
		}

		if( event == EVENT_COUNT_MANA && affect_me(player, card) ){
			if( mana_producer(p, c, EVENT_CAN_ACTIVATE) ){
				declare_mana_available_hex(p, COLOR_TEST_ANY_COLORED, amt);
			}
		}
	}

	if( ! IS_AURA_EVENT(player, card, event) ){
		return 0;
	}

	target_definition_t td;
	default_target_definition(player, card, &td, TYPE_LAND);
	td.preferred_controller = player;
	td.allowed_controller = player;

	card_instance_t *instance = get_card_instance( player, card );

	if( event == EVENT_CAN_CAST ){
		return targeted_aura(player, card, event, &td, NULL);
	}

	if( event == EVENT_CAST_SPELL && affect_me(player, card) ){
		instance->number_of_targets = 0;
		ai_modifier+=100;
		new_pick_target(&td, "Select target land you control.", 0, 1 | GS_LITERAL_PROMPT);
	}

	if( event == EVENT_RESOLVE_SPELL ){
		return targeted_aura(player, card, event, &td, NULL);
	}

	return 0;
}

