	}

	int i, *deck = deck_ptr[player];
	for (i = amount - 1; i >= 0; --i){
			if( has_subtype(-1, deck[i], subtype) ){
				add_card_to_hand(player, deck[i]);
				remove_card_from_deck(player, i);
				result++;
				amount--;
			}
	}
	if( amount > 0 ){
		put_top_x_on_bottom(player, player, amount);
	}

	return result;
}

