			int amount = count_counters(instance->parent_controller, instance->parent_card, COUNTER_DEVOTION);
			pump_until_eot(player, instance->parent_card, instance->targets[0].player, instance->targets[0].card, -amount, -amount);
		}
	}

	return 0;
}

