	  inst->counter_toughness -= 2;
	  inst->regen_status |= KEYWORD_RECALC_TOUGHNESS;
	  if (inst->damage_target_player == AI && current_turn == AI && !(ench->state & STATE_ATTACKED))
		ai_modifier -= 60;
	}
  return rval;
}

