													NULL, NULL)
		};
		int priorities[3] = {
							0,
							30-(count_counters(player, card, COUNTER_P1_P1)*10),
							count_counters(player, card, COUNTER_P1_P1)*10
		};
		int choice = DIALOG(player, card, event, DLG_RANDOM,
