							"Pentavite to counter", new_can_sacrifice_as_cost(player, card, &test), current_turn == player ? 10 : 1);
		if( ! choice ){
			spell_fizzled = 1;
			return 0;
		}
		switch (choice)
		{
			case CHOICE_TOKEN:
			{
