						if (selected != -1){
							from_graveyard_to_deck(player, selected, 2);
							++num_validated;
						}
					}
					if (num_validated > 1){
						rearrange_bottom_x(player, player, num_validated);
					}
					break;
				}
			}
		}
	}

	return global_enchantment(player, card, event);
}

