	enum{
		CHOICE_LEVEL_UP = 1,
		CHOICE_TWINCAST
	};

	if( event == EVENT_CAN_ACTIVATE ){
		if( generic_activated_ability(player, card, event, GAA_SPELL_ON_STACK | GAA_UNTAPPED, MANACOST_U(2), 0, &td, NULL) &&
			count_counters(player, card, COUNTER_LEVEL) >= 2 )
