	}

	if(event == EVENT_ACTIVATE ){
		int abils[3] = {
						0,
						generic_activated_ability(player, card, event, GAA_CAN_SORCERY_BE_PLAYED, MANACOST0, 0,
												    NULL, NULL),
						count_counters(player, card, COUNTER_LEVEL) >= 2 &&
