		};
		int choice = DIALOG(player, card, event, DLG_RANDOM, DLG_AUTOCHOOSE_IF_1,
							"Get mana", abils[1], 1,
							"Skip turn & get Eon counter", abils[2] && ! paying_mana() ? 1 : 0, 5,
