		    alternate_legacy_text(1, player, skip_next_turn(player, card, player));
		}
		if( instance->info_slot == CHOICE_TIME_WALK ){
			alternate_legacy_text(2, player, time_walk_effect(instance->parent_controller, instance->parent_card));
		}
	}

	return 0;
}

