					tok->targets[1].card = 0;
				}
				tok->targets[1].card |= keyword;
			}
		}
	}

	return generic_activated_ability(player, card, event, GAA_CAN_TARGET | GAA_DISCARD, MANACOST_GW(1, 1), 0, &td, "TARGET_CREATURE");
