    strcpy(rules_text, cards_txt[src_csvid].legacy_text);
    type_text = "Effect";
    if (inst.eot_toughness)
      legacy_name_or_text(rules_text, player, card, EVENT_SET_LEGACY_EFFECT_TEXT);
    break;
